insert into public.tours (slug, code, length, interests, accommodation_offered, accommodation_price_from_idr, part_prices, car_prices, photo, photo_credit, text, position, published) values
  ('borobudur-prambanan', 'A', 'day-trip', array['temples']::text[], true, null, '[{"avanza":450000,"xenia":450000,"innova-reborn":610000,"innova-zenix":680000,"hiace":970000},{"avanza":400000,"xenia":400000,"innova-reborn":540000,"innova-zenix":600000,"hiace":860000}]'::jsonb, '{"avanza":550000,"xenia":550000,"innova-reborn":750000,"innova-zenix":830000,"hiace":1190000}'::jsonb, '/photos/borobudur.jpg', '{"subject":"Borobudur","author":"Justine Hong","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Borobudur_Sunrise_2012-01-05.jpg"}'::jsonb, '{"en":{"name":"Borobudur & Prambanan","summary":"Java''s two great temples in one day: the Buddhist stupas of Borobudur and the Hindu towers of Prambanan.","duration":"Day trip, there and back","destinations":["Borobudur temple","Prambanan temple"],"dropOffs":[],"photoAlt":"Stone stupas on the top terrace of Borobudur at sunrise, with mist over the forest below","parts":["Borobudur only","Prambanan only"]},"id":{"name":"Borobudur & Prambanan","summary":"Dua candi terbesar di Jawa dalam sehari: stupa Buddha di Candi Borobudur dan menara Hindu di Candi Prambanan.","duration":"Perjalanan sehari, PP","destinations":["Candi Borobudur","Candi Prambanan"],"dropOffs":[],"photoAlt":"Stupa batu di teras atas Borobudur saat matahari terbit, dengan kabut di atas hutan di bawahnya","parts":["Borobudur saja","Prambanan saja"]},"fr":{"name":"Borobudur & Prambanan","summary":"Les deux grands temples de Java en une journée : les stupas bouddhistes de Borobudur et les tours hindoues de Prambanan.","duration":"À la journée, aller-retour","destinations":["Temple de Borobudur","Temple de Prambanan"],"dropOffs":[],"photoAlt":"Stupas de pierre sur la terrasse supérieure de Borobudur au lever du soleil, avec la brume sur la forêt en contrebas","parts":["Borobudur seulement","Prambanan seulement"]}}'::jsonb, 0, true),
  ('borobudur-heritage', 'B', 'day-trip', array['temples', 'culture']::text[], true, null, '[{"avanza":450000,"xenia":450000,"innova-reborn":610000,"innova-zenix":680000,"hiace":970000},{"avanza":400000,"xenia":400000,"innova-reborn":540000,"innova-zenix":600000,"hiace":860000}]'::jsonb, '{"avanza":550000,"xenia":550000,"innova-reborn":750000,"innova-zenix":830000,"hiace":1190000}'::jsonb, '/photos/kraton.jpg', '{"subject":"Kraton","author":"Jorge Franganillo","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Kraton_Ngayogyakarta_Hadiningrat_(49797461187).jpg"}'::jsonb, '{"en":{"name":"Borobudur & Yogyakarta Heritage","summary":"Borobudur in the morning, then back to the city for the Sultan''s palace and the old royal water garden.","duration":"Day trip, there and back","destinations":["Borobudur temple","Kraton Yogyakarta, the Sultan''s palace","Taman Sari water castle"],"dropOffs":[],"photoAlt":"An open pavilion with carved, painted pillars inside the Kraton of Yogyakarta","parts":["Borobudur only","Yogyakarta heritage only"]},"id":{"name":"Borobudur & Wisata Sejarah Yogyakarta","summary":"Candi Borobudur di pagi hari, lalu kembali ke kota untuk mengunjungi keraton Sultan dan taman air kerajaan.","duration":"Perjalanan sehari, PP","destinations":["Candi Borobudur","Kraton Yogyakarta, istana Sultan","Taman Sari"],"dropOffs":[],"photoAlt":"Pendapa terbuka dengan tiang-tiang berukir dan berwarna di dalam Kraton Yogyakarta","parts":["Borobudur saja","Wisata sejarah Yogyakarta saja"]},"fr":{"name":"Borobudur & patrimoine de Yogyakarta","summary":"Borobudur le matin, puis retour en ville pour le palais du Sultan et l''ancien jardin d''eau royal.","duration":"À la journée, aller-retour","destinations":["Temple de Borobudur","Kraton de Yogyakarta, le palais du Sultan","Château d''eau de Taman Sari"],"dropOffs":[],"photoAlt":"Un pavillon ouvert aux piliers sculptés et peints dans le Kraton de Yogyakarta","parts":["Borobudur seulement","Patrimoine de Yogyakarta seulement"]}}'::jsonb, 1, true),
  ('jomblang-pindul', 'C', 'day-trip', array['adventure', 'nature']::text[], true, null, '[{"avanza":400000,"xenia":400000,"innova-reborn":540000,"innova-zenix":600000,"hiace":860000},{"avanza":400000,"xenia":400000,"innova-reborn":540000,"innova-zenix":600000,"hiace":860000}]'::jsonb, '{"avanza":500000,"xenia":500000,"innova-reborn":680000,"innova-zenix":750000,"hiace":1080000}'::jsonb, '/photos/jomblang.jpg', '{"subject":"Jomblang cave","author":"Arie Basuki","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Cahaya_Goa_Jomblang.jpg"}'::jsonb, '{"en":{"name":"Jomblang & Pindul Caves","summary":"Down into Jomblang''s collapsed cave where light falls from the forest above, then tubing through Pindul cave.","duration":"Day trip, there and back","destinations":["Jomblang cave","Pindul cave"],"dropOffs":[],"photoAlt":"A beam of sunlight falling into Jomblang cave onto visitors in helmets","parts":["Jomblang Cave only","Pindul Cave only"]},"id":{"name":"Goa Jomblang & Goa Pindul","summary":"Turun ke dalam Goa Jomblang tempat cahaya jatuh dari hutan di atasnya, lalu cave tubing menyusuri Goa Pindul.","duration":"Perjalanan sehari, PP","destinations":["Goa Jomblang","Goa Pindul"],"dropOffs":[],"photoAlt":"Seberkas cahaya matahari masuk ke Goa Jomblang menyinari pengunjung berhelm","parts":["Goa Jomblang saja","Goa Pindul saja"]},"fr":{"name":"Grottes de Jomblang & Pindul","summary":"Descente dans la grotte effondrée de Jomblang, où la lumière tombe de la forêt au-dessus, puis descente en bouée dans la grotte de Pindul.","duration":"À la journée, aller-retour","destinations":["Grotte de Jomblang","Grotte de Pindul"],"dropOffs":[],"photoAlt":"Un rayon de soleil tombe dans la grotte de Jomblang sur des visiteurs casqués","parts":["Grotte de Jomblang seulement","Grotte de Pindul seulement"]}}'::jsonb, 2, true),
  ('merapi-prambanan-ramayana', 'D', 'day-trip', array['temples', 'culture', 'adventure']::text[], true, null, '[{"avanza":500000,"xenia":500000,"innova-reborn":680000,"innova-zenix":750000,"hiace":1080000},{"avanza":500000,"xenia":500000,"innova-reborn":680000,"innova-zenix":750000,"hiace":1080000}]'::jsonb, '{"avanza":750000,"xenia":750000,"innova-reborn":1020000,"innova-zenix":1130000,"hiace":1620000}'::jsonb, '/photos/prambanan.jpg', '{"subject":"Prambanan","author":"CEphoto, Uwe Aranas","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Yogyakarta_Indonesia_Prambanan-temple-complex-23.jpg"}'::jsonb, '{"en":{"name":"Merapi Lava Tour, Prambanan & Ramayana Ballet","summary":"A jeep across Merapi''s lava fields, Prambanan in the afternoon, and the Ramayana ballet in the evening.","duration":"Day trip, there and back","destinations":["Merapi lava tour","Prambanan temple","Ramayana ballet"],"dropOffs":[],"photoAlt":"The carved stone towers of Prambanan temple under a cloudy sky","parts":["Merapi Lava Tour only","Prambanan & Ramayana Ballet only"]},"id":{"name":"Lava Tour Merapi, Prambanan & Sendratari Ramayana","summary":"Naik jip melintasi bekas aliran lahar Merapi, Candi Prambanan di sore hari, dan Sendratari Ramayana di malam hari.","duration":"Perjalanan sehari, PP","destinations":["Lava tour Merapi","Candi Prambanan","Sendratari Ramayana"],"dropOffs":[],"photoAlt":"Menara batu berukir Candi Prambanan di bawah langit berawan","parts":["Lava Tour Merapi saja","Prambanan & Sendratari Ramayana saja"]},"fr":{"name":"Lava tour du Merapi, Prambanan & ballet du Ramayana","summary":"Une jeep à travers les coulées de lave du Merapi, Prambanan l''après-midi et le ballet du Ramayana le soir.","duration":"À la journée, aller-retour","destinations":["Lava tour du Merapi","Temple de Prambanan","Ballet du Ramayana"],"dropOffs":[],"photoAlt":"Les tours de pierre sculptées du temple de Prambanan sous un ciel nuageux","parts":["Lava tour du Merapi seulement","Prambanan & ballet du Ramayana seulement"]}}'::jsonb, 3, true),
  ('bromo-madakaripura', 'E', 'multi-day', array['nature', 'adventure']::text[], true, null, '[{"avanza":2400000,"xenia":2400000,"innova-reborn":3240000,"innova-zenix":3600000,"hiace":5160000}]'::jsonb, '{"avanza":2700000,"xenia":2700000,"innova-reborn":3650000,"innova-zenix":4050000,"hiace":5810000}'::jsonb, '/photos/bromo.jpg', '{"subject":"Bromo","author":"Thomas Hirsch","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Mount_Bromo_at_sunrise,_showing_its_volcanoes_and_Mount_Semeru_(background).jpg"}'::jsonb, '{"en":{"name":"Bromo & Madakaripura","summary":"Overnight to East Java for sunrise over Bromo''s sea of sand, then the cliff-walled Madakaripura waterfall.","duration":"2 days, 1 night","destinations":["Mount Bromo","Madakaripura waterfall"],"dropOffs":["Back to your hotel in Jogja","Juanda Airport, Surabaya","Ketapang port, Banyuwangi, via Ijen crater, for the ferry to Bali"],"photoAlt":"Mount Bromo''s smoking crater at sunrise, with Mount Semeru behind","parts":["Bromo only"]},"id":{"name":"Bromo & Madakaripura","summary":"Perjalanan malam ke Jawa Timur untuk sunrise di atas lautan pasir Bromo, lalu Air Terjun Madakaripura yang diapit tebing.","duration":"2 hari 1 malam","destinations":["Gunung Bromo","Air Terjun Madakaripura"],"dropOffs":["Kembali ke hotel Anda di Jogja","Bandara Juanda, Surabaya","Pelabuhan Ketapang, Banyuwangi, lewat Kawah Ijen, lanjut kapal ke Bali"],"photoAlt":"Kawah Gunung Bromo yang berasap saat matahari terbit, dengan Gunung Semeru di belakangnya","parts":["Bromo saja"]},"fr":{"name":"Bromo & Madakaripura","summary":"Une nuit de route vers Java oriental pour le lever du soleil sur la mer de sable du Bromo, puis la cascade de Madakaripura entre ses falaises.","duration":"2 jours, 1 nuit","destinations":["Mont Bromo","Cascade de Madakaripura"],"dropOffs":["Retour à votre hôtel à Jogja","Aéroport de Juanda, Surabaya","Port de Ketapang, Banyuwangi, via le cratère de l''Ijen, pour le ferry vers Bali"],"photoAlt":"Le cratère fumant du mont Bromo au lever du soleil, avec le mont Semeru en arrière-plan","parts":["Bromo seulement"]}}'::jsonb, 4, true),
  ('tumpak-sewu', 'F', 'multi-day', array['nature']::text[], true, null, '[]'::jsonb, '{}'::jsonb, '/photos/tumpak-sewu.jpg', '{"subject":"Tumpak Sewu","author":"Muhyiddin","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Tumpak_sewu_waterfall.jpg"}'::jsonb, '{"en":{"name":"Tumpak Sewu Waterfalls","summary":"The curtain of falls at Tumpak Sewu under Mount Semeru, with Kabut Pelangi and Kapas Biru nearby.","duration":"Multi-day, ask us","destinations":["Tumpak Sewu waterfall","Kabut Pelangi waterfall","Kapas Biru waterfall"],"dropOffs":["Back to your hotel in Jogja","Juanda Airport, Surabaya","Ketapang port, Banyuwangi, via Ijen crater, for the ferry to Bali"],"photoAlt":"Dozens of thin waterfalls pouring into a green canyon at Tumpak Sewu","parts":[]},"id":{"name":"Air Terjun Tumpak Sewu","summary":"Tirai air terjun Tumpak Sewu di kaki Gunung Semeru, dengan Kabut Pelangi dan Kapas Biru di dekatnya.","duration":"Beberapa hari, hubungi kami","destinations":["Air Terjun Tumpak Sewu","Air Terjun Kabut Pelangi","Air Terjun Kapas Biru"],"dropOffs":["Kembali ke hotel Anda di Jogja","Bandara Juanda, Surabaya","Pelabuhan Ketapang, Banyuwangi, lewat Kawah Ijen, lanjut kapal ke Bali"],"photoAlt":"Puluhan air terjun kecil mengalir ke ngarai hijau di Tumpak Sewu","parts":[]},"fr":{"name":"Cascades de Tumpak Sewu","summary":"Le rideau de chutes de Tumpak Sewu au pied du mont Semeru, avec Kabut Pelangi et Kapas Biru tout près.","duration":"Plusieurs jours, nous consulter","destinations":["Cascade de Tumpak Sewu","Cascade de Kabut Pelangi","Cascade de Kapas Biru"],"dropOffs":["Retour à votre hôtel à Jogja","Aéroport de Juanda, Surabaya","Port de Ketapang, Banyuwangi, via le cratère de l''Ijen, pour le ferry vers Bali"],"photoAlt":"Des dizaines de fines cascades se jetant dans un canyon verdoyant à Tumpak Sewu","parts":[]}}'::jsonb, 5, true),
  ('ijen-baluran', 'G', 'multi-day', array['nature', 'adventure']::text[], true, null, '[{"avanza":3000000,"xenia":3000000,"innova-reborn":4050000,"innova-zenix":4500000,"hiace":6450000}]'::jsonb, '{"avanza":3500000,"xenia":3500000,"innova-reborn":4730000,"innova-zenix":5250000,"hiace":7530000}'::jsonb, '/photos/ijen.jpg', '{"subject":"Kawah Ijen","author":"Sémhur","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Sulfur_mining_in_Kawah_Ijen_-_Indonesia_-_20110608.jpg"}'::jsonb, '{"en":{"name":"Ijen & Baluran","summary":"The turquoise crater lake of Kawah Ijen, then the savanna of Baluran national park at the eastern tip of Java.","duration":"2 days, 1 night","destinations":["Kawah Ijen crater","Baluran national park"],"dropOffs":["Back to your hotel in Jogja","Juanda Airport, Surabaya","Ketapang port, Banyuwangi, for the ferry to Bali"],"photoAlt":"Steam rising over the turquoise acid lake inside the Ijen crater","parts":["Ijen only"]},"id":{"name":"Ijen & Baluran","summary":"Danau kawah biru toska di Kawah Ijen, lalu sabana Taman Nasional Baluran di ujung timur Pulau Jawa.","duration":"2 hari 1 malam","destinations":["Kawah Ijen","Taman Nasional Baluran"],"dropOffs":["Kembali ke hotel Anda di Jogja","Bandara Juanda, Surabaya","Pelabuhan Ketapang, Banyuwangi, lanjut kapal ke Bali"],"photoAlt":"Uap mengepul di atas danau asam biru toska di dalam Kawah Ijen","parts":["Ijen saja"]},"fr":{"name":"Ijen & Baluran","summary":"Le lac de cratère turquoise du Kawah Ijen, puis la savane du parc national de Baluran, à la pointe est de Java.","duration":"2 jours, 1 nuit","destinations":["Cratère du Kawah Ijen","Parc national de Baluran"],"dropOffs":["Retour à votre hôtel à Jogja","Aéroport de Juanda, Surabaya","Port de Ketapang, Banyuwangi, pour le ferry vers Bali"],"photoAlt":"De la vapeur s''élève au-dessus du lac acide turquoise dans le cratère de l''Ijen","parts":["Ijen seulement"]}}'::jsonb, 6, true),
  ('dieng-highland', 'H', 'day-trip', array['nature', 'temples']::text[], true, null, '[]'::jsonb, '{"avanza":1500000,"xenia":1500000,"innova-reborn":2030000,"innova-zenix":2250000,"hiace":3230000}'::jsonb, '/photos/dieng.jpg', '{"subject":"Telaga Warna, Dieng","author":"Haridi123","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Telaga_Warna_Dieng_Jawa_Tengah.jpg"}'::jsonb, '{"en":{"name":"Dieng Highland Escape","summary":"Sunrise from Sikunir hill, tea gardens, the coloured lake of Telaga Warna and the old Arjuna temples.","duration":"1 day, or 2 days and 1 night","destinations":["Sikunir sunrise","Dieng tea gardens","Telaga Warna lake","Arjuna temples"],"dropOffs":[],"photoAlt":"The green Telaga Warna lake among forested hills on the Dieng plateau","parts":[]},"id":{"name":"Dieng Highland Escape","summary":"Sunrise dari Bukit Sikunir, kebun teh, Telaga Warna yang berwarna-warni, dan kompleks Candi Arjuna yang kuno.","duration":"1 hari, atau 2 hari 1 malam","destinations":["Sunrise Bukit Sikunir","Kebun teh Dieng","Telaga Warna","Candi Arjuna"],"dropOffs":[],"photoAlt":"Telaga Warna yang hijau di antara perbukitan berhutan di Dataran Tinggi Dieng","parts":[]},"fr":{"name":"Escapade sur le plateau de Dieng","summary":"Lever de soleil depuis la colline de Sikunir, plantations de thé, le lac coloré de Telaga Warna et les anciens temples d''Arjuna.","duration":"1 jour, ou 2 jours et 1 nuit","destinations":["Lever de soleil à Sikunir","Plantations de thé de Dieng","Lac de Telaga Warna","Temples d''Arjuna"],"dropOffs":[],"photoAlt":"Le lac vert de Telaga Warna entre des collines boisées sur le plateau de Dieng","parts":[]}}'::jsonb, 7, true),
  ('jogja-beach-city', 'I', 'day-trip', array['nature', 'culture']::text[], true, null, '[]'::jsonb, '{"avanza":500000,"xenia":500000,"innova-reborn":680000,"innova-zenix":750000,"hiace":1080000}'::jsonb, '/photos/parangtritis.jpg', '{"subject":"Parangtritis","author":"Midori","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Parangtritis_Beach_2011_2.JPG"}'::jsonb, '{"en":{"name":"Jogja Beach & City Escape","summary":"Parangtritis beach and its sand dunes, sunset at Obelix Sea View, and the evening on Malioboro street.","duration":"Day trip, there and back","destinations":["Parangtritis beach","Gumuk Pasir sand dunes","Obelix Sea View","Malioboro street"],"dropOffs":[],"photoAlt":"A horse-drawn cart on the sand at Parangtritis beach","parts":[]},"id":{"name":"Jogja Beach & City Escape","summary":"Pantai Parangtritis dan Gumuk Pasir, sunset di Obelix Sea View, lalu malam di Jalan Malioboro.","duration":"Perjalanan sehari, PP","destinations":["Pantai Parangtritis","Gumuk Pasir","Obelix Sea View","Jalan Malioboro"],"dropOffs":[],"photoAlt":"Andong yang ditarik kuda di atas pasir Pantai Parangtritis","parts":[]},"fr":{"name":"Escapade plage et ville à Jogja","summary":"La plage de Parangtritis et ses dunes de sable, le coucher de soleil à Obelix Sea View, et la soirée rue Malioboro.","duration":"À la journée, aller-retour","destinations":["Plage de Parangtritis","Dunes de Gumuk Pasir","Obelix Sea View","Rue Malioboro"],"dropOffs":[],"photoAlt":"Une charrette tirée par un cheval sur le sable de la plage de Parangtritis","parts":[]}}'::jsonb, 8, true),
  ('merapi-adventure', 'J', 'day-trip', array['adventure', 'nature']::text[], true, null, '[]'::jsonb, '{"avanza":450000,"xenia":450000,"innova-reborn":610000,"innova-zenix":680000,"hiace":970000}'::jsonb, '/photos/merapi.jpg', '{"subject":"Merapi","author":"Kang Henry Irawan","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Gagahnya_Merapi.jpg"}'::jsonb, '{"en":{"name":"Merapi Adventure","summary":"Up the slopes of Java''s most active volcano for a lava tour by jeep and ATV rides around Kaliurang.","duration":"Day trip, there and back","destinations":["Merapi lava tour","Kaliurang ATV adventure"],"dropOffs":[],"photoAlt":"The grey, bare cone of Mount Merapi seen from the forest below","parts":[]},"id":{"name":"Merapi Adventure","summary":"Naik ke lereng gunung api paling aktif di Jawa untuk lava tour dengan jip dan naik ATV di sekitar Kaliurang.","duration":"Perjalanan sehari, PP","destinations":["Lava tour Merapi","Petualangan ATV Kaliurang"],"dropOffs":[],"photoAlt":"Puncak Gunung Merapi yang gundul dan abu-abu, terlihat dari hutan di bawahnya","parts":[]},"fr":{"name":"Aventure au Merapi","summary":"Sur les pentes du volcan le plus actif de Java pour un lava tour en jeep et des balades en quad autour de Kaliurang.","duration":"À la journée, aller-retour","destinations":["Lava tour du Merapi","Quad à Kaliurang"],"dropOffs":[],"photoAlt":"Le cône gris et nu du mont Merapi vu depuis la forêt en contrebas","parts":[]}}'::jsonb, 9, true),
  ('gunungkidul-coast', 'K', 'day-trip', array['nature', 'adventure']::text[], true, null, '[]'::jsonb, '{"avanza":700000,"xenia":700000,"innova-reborn":950000,"innova-zenix":1050000,"hiace":1510000}'::jsonb, '/photos/timang.jpg', '{"subject":"Timang beach","author":"Yasuspade","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Gondala_pantai_Timang_-_Gunung_Kidul,_DIY.jpg"}'::jsonb, '{"en":{"name":"Gunungkidul Coastal Adventure","summary":"The wooden gondola out to Timang''s rock, then the quiet coves of Drini and Sadranan.","duration":"Day trip, there and back","destinations":["Timang beach","Drini beach","Sadranan beach"],"dropOffs":[],"photoAlt":"The wooden gondola that crosses to the rock island at Timang beach","parts":[]},"id":{"name":"Petualangan Pantai Gunungkidul","summary":"Gondola kayu menyeberang ke batu karang di Pantai Timang, lalu teluk-teluk tenang di Pantai Drini dan Pantai Sadranan.","duration":"Perjalanan sehari, PP","destinations":["Pantai Timang","Pantai Drini","Pantai Sadranan"],"dropOffs":[],"photoAlt":"Gondola kayu yang menyeberang ke pulau karang di Pantai Timang","parts":[]},"fr":{"name":"Aventure sur la côte de Gunungkidul","summary":"La nacelle en bois jusqu''au rocher de Timang, puis les criques tranquilles de Drini et Sadranan.","duration":"À la journée, aller-retour","destinations":["Plage de Timang","Plage de Drini","Plage de Sadranan"],"dropOffs":[],"photoAlt":"La nacelle en bois qui traverse jusqu''à l''îlot rocheux de la plage de Timang","parts":[]}}'::jsonb, 10, true),
  ('magelang-sunrise', 'L', 'day-trip', array['nature', 'adventure', 'culture']::text[], true, null, '[]'::jsonb, '{"avanza":550000,"xenia":550000,"innova-reborn":750000,"innova-zenix":830000,"hiace":1190000}'::jsonb, '/photos/setumbu.jpg', '{"subject":"Punthuk Setumbu","author":"Ridwanad","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Sunrise_di_punthuk_setumbu.jpg"}'::jsonb, '{"en":{"name":"Magelang Sunrise & Adventure","summary":"Sunrise over Borobudur from Punthuk Setumbu, the odd Gereja Ayam church, and rafting on the Elo river.","duration":"Day trip, there and back","destinations":["Punthuk Setumbu sunrise","Gereja Ayam","Elo river rafting"],"dropOffs":[],"photoAlt":"Sunrise over the mountains seen from Punthuk Setumbu hill","parts":[]},"id":{"name":"Sunrise & Petualangan Magelang","summary":"Sunrise di atas Borobudur dari Punthuk Setumbu, Gereja Ayam yang unik, dan Rafting Sungai Elo.","duration":"Perjalanan sehari, PP","destinations":["Sunrise Punthuk Setumbu","Gereja Ayam","Rafting Sungai Elo"],"dropOffs":[],"photoAlt":"Matahari terbit di atas pegunungan, dilihat dari Bukit Punthuk Setumbu","parts":[]},"fr":{"name":"Lever de soleil et aventure à Magelang","summary":"Le lever du soleil sur Borobudur depuis Punthuk Setumbu, l''étonnante église Gereja Ayam et du rafting sur la rivière Elo.","duration":"À la journée, aller-retour","destinations":["Lever de soleil à Punthuk Setumbu","Gereja Ayam","Rafting sur la rivière Elo"],"dropOffs":[],"photoAlt":"Le lever du soleil sur les montagnes vu depuis la colline de Punthuk Setumbu","parts":[]}}'::jsonb, 11, true),
  ('jogja-scenic-sunset', 'M', 'day-trip', array['nature']::text[], true, null, '[]'::jsonb, '{"avanza":650000,"xenia":650000,"innova-reborn":880000,"innova-zenix":980000,"hiace":1400000}'::jsonb, '/photos/breksi.jpg', '{"subject":"Tebing Breksi","author":"Firzafp","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Tebing_Breksi_-_Sleman,_YO_(24_January_2023)_01.jpg"}'::jsonb, '{"en":{"name":"Yogyakarta Scenic & Sunset","summary":"Clifftop views at HeHa Sky View and HeHa Ocean View, Puncak Segoro, and the carved quarry walls of Tebing Breksi.","duration":"Day trip, there and back","destinations":["HeHa Sky View","HeHa Ocean View","Puncak Segoro","Tebing Breksi"],"dropOffs":[],"photoAlt":"The carved limestone cliff face of Tebing Breksi","parts":[]},"id":{"name":"Yogyakarta Scenic & Sunset","summary":"Pemandangan dari atas tebing di HeHa Sky View dan HeHa Ocean View, Puncak Segoro, dan dinding bekas tambang berukir di Tebing Breksi.","duration":"Perjalanan sehari, PP","destinations":["HeHa Sky View","HeHa Ocean View","Puncak Segoro","Tebing Breksi"],"dropOffs":[],"photoAlt":"Dinding tebing kapur berukir di Tebing Breksi","parts":[]},"fr":{"name":"Panoramas et coucher de soleil à Yogyakarta","summary":"Vues du haut des falaises à HeHa Sky View et HeHa Ocean View, Puncak Segoro et les parois taillées de l''ancienne carrière de Tebing Breksi.","duration":"À la journée, aller-retour","destinations":["HeHa Sky View","HeHa Ocean View","Puncak Segoro","Tebing Breksi"],"dropOffs":[],"photoAlt":"La paroi de calcaire sculptée de Tebing Breksi","parts":[]}}'::jsonb, 12, true),
  ('water-adventure', 'N', 'day-trip', array['adventure', 'nature']::text[], true, null, '[]'::jsonb, '{}'::jsonb, '/photos/kedung-pedut.jpg', '{"subject":"Kedung Pedut","author":"Hatfina nusratina","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Kedung-pedut_3.jpg"}'::jsonb, '{"en":{"name":"Water & Adventure","summary":"A day of rivers and falls: Kedung Pedut, the Blue Lagoon, Sri Gethuk waterfall and rafting on the Elo.","duration":"Day trip, there and back","destinations":["Kedung Pedut waterfall","Blue Lagoon","Sri Gethuk waterfall","Elo river rafting"],"dropOffs":[],"photoAlt":"Water running over terraced rocks at Kedung Pedut waterfall","parts":[]},"id":{"name":"Water & Adventure","summary":"Sehari bermain air di sungai dan air terjun: Kedung Pedut, Blue Lagoon, Air Terjun Sri Gethuk, dan Rafting Sungai Elo.","duration":"Perjalanan sehari, PP","destinations":["Air Terjun Kedung Pedut","Blue Lagoon","Air Terjun Sri Gethuk","Rafting Sungai Elo"],"dropOffs":[],"photoAlt":"Air mengalir di atas bebatuan bertingkat di Air Terjun Kedung Pedut","parts":[]},"fr":{"name":"Eau & aventure","summary":"Une journée de rivières et de cascades : Kedung Pedut, le Blue Lagoon, la cascade de Sri Gethuk et du rafting sur l''Elo.","duration":"À la journée, aller-retour","destinations":["Cascade de Kedung Pedut","Blue Lagoon","Cascade de Sri Gethuk","Rafting sur la rivière Elo"],"dropOffs":[],"photoAlt":"L''eau ruisselle sur les rochers en terrasses de la cascade de Kedung Pedut","parts":[]}}'::jsonb, 13, true),
  ('nature-scenic', 'O', 'day-trip', array['nature']::text[], true, null, '[]'::jsonb, '{}'::jsonb, '/photos/menoreh.jpg', '{"subject":"Menoreh hills","author":"Febri Ady Prasetyo","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Pegunungan_Menoreh_dilihat_dari_Punthuk_Setumbu.jpg"}'::jsonb, '{"en":{"name":"Nature & Scenic","summary":"The Menoreh hills and Magelang''s highlands: Tumpeng Menoreh, Pule Payung, Nepal van Java, Sukomakmur and Ketep Pass.","duration":"Day trip, there and back","destinations":["Tumpeng Menoreh","Pule Payung","Nepal van Java","Negeri Sayur Sukomakmur","Ketep Pass"],"dropOffs":[],"photoAlt":"Green valleys of the Menoreh hills seen from above","parts":[]},"id":{"name":"Nature & Scenic","summary":"Perbukitan Menoreh dan dataran tinggi Magelang: Tumpeng Menoreh, Pule Payung, Nepal van Java, Sukomakmur, dan Ketep Pass.","duration":"Perjalanan sehari, PP","destinations":["Tumpeng Menoreh","Pule Payung","Nepal van Java","Negeri Sayur Sukomakmur","Ketep Pass"],"dropOffs":[],"photoAlt":"Lembah hijau Perbukitan Menoreh dilihat dari atas","parts":[]},"fr":{"name":"Nature & panoramas","summary":"Les collines de Menoreh et les hauteurs de Magelang : Tumpeng Menoreh, Pule Payung, Nepal van Java, Sukomakmur et Ketep Pass.","duration":"À la journée, aller-retour","destinations":["Tumpeng Menoreh","Pule Payung","Nepal van Java","Negeri Sayur Sukomakmur","Ketep Pass"],"dropOffs":[],"photoAlt":"Les vallées verdoyantes des collines de Menoreh vues d''en haut","parts":[]}}'::jsonb, 14, true);
