insert into public.articles (slug, text, cover, photos, published_on, published) values
  ('sample-merapi-to-bromo-in-four-days', '{"en":{"title":"Sample: from Merapi to Bromo in four days","excerpt":"Two guests from Germany crossed Java with one car and one driver, from the slopes of Merapi to sunrise over Bromo.","body":"This is a sample article, so you can see how an article looks. Write your own in the admin panel under Artikel.\n\nOur guests landed at YIA in the afternoon. Their driver met them at arrivals and took them to their hotel in Jogja, with a stop for dinner on the way.\n\n## The route\n\n- Jeep lava tour on Merapi\n- Sunset at the Merapi gate\n- The long drive east to Bromo\n- Madakaripura waterfall\n\n## On the road\n\nThe drive from Jogja to Bromo takes most of a day. We stopped whenever they wanted: for coffee, for photos of the rice fields, and for lunch at a small warung their driver knew.\n\nAt Bromo they rode a jeep up to the viewpoint before dawn and watched the sun come up over the crater."},"id":{"title":"Contoh: dari Merapi ke Bromo dalam empat hari","excerpt":"Dua tamu dari Jerman menjelajahi Jawa dengan satu mobil dan satu sopir, dari lereng Merapi sampai matahari terbit di Bromo.","body":"Ini contoh artikel, supaya terlihat bentuk sebuah artikel. Tulis artikel Anda sendiri di panel admin, menu Artikel.\n\nTamu kami mendarat di YIA sore hari. Sopir menjemput di pintu kedatangan dan mengantar ke hotel di Jogja, mampir makan malam di jalan.\n\n## Rutenya\n\n- Jeep lava tour Merapi\n- Senja di gerbang Merapi\n- Perjalanan panjang ke timur, ke Bromo\n- Air terjun Madakaripura\n\n## Di perjalanan\n\nPerjalanan dari Jogja ke Bromo hampir seharian. Kami berhenti kapan pun tamu mau: untuk kopi, foto sawah, dan makan siang di warung langganan sopirnya.\n\nDi Bromo mereka naik jeep ke titik pandang sebelum subuh dan melihat matahari terbit di atas kawah."}}'::jsonb, '/photos/bromo.jpg', array['/photos/merapi.jpg', '/photos/setumbu.jpg', '/photos/tumpak-sewu.jpg', '/photos/bromo.jpg']::text[], '2026-10-05', true),
  ('sample-a-day-at-borobudur-and-prambanan', '{"en":{"title":"Sample: a day at Borobudur and Prambanan","excerpt":"A family from Malaysia saw both temples in one day, with an early start to beat the heat.","body":"This is a sample article. Write your own in the admin panel under Artikel.\n\nWe picked the family up from their hotel at 5 in the morning to be at Borobudur when it opened. By lunch they were back in the city, and in the afternoon we drove to Prambanan for the golden light."},"id":{"title":"Contoh: sehari di Borobudur dan Prambanan","excerpt":"Satu keluarga dari Malaysia melihat kedua candi dalam sehari, berangkat pagi sebelum panas.","body":"Ini contoh artikel. Tulis artikel Anda sendiri di panel admin, menu Artikel.\n\nKami menjemput keluarga ini di hotel pukul 5 pagi supaya tiba di Borobudur saat buka. Siang mereka sudah kembali ke kota, dan sore harinya kami ke Prambanan untuk cahaya senja."}}'::jsonb, '/photos/borobudur.jpg', array['/photos/borobudur.jpg', '/photos/prambanan.jpg']::text[], '2026-09-29', true),
  ('sample-caves-and-beaches-of-gunungkidul', '{"en":{"title":"Sample: the caves and beaches of Gunungkidul","excerpt":"Down into Jomblang Cave in the morning, across to Timang Beach by gondola in the afternoon.","body":"This is a sample article. Write your own in the admin panel under Artikel.\n\nGunungkidul is two hours south of Jogja. Our guest from France wanted caves and the sea, so we did both in one long day."},"id":{"title":"Contoh: goa dan pantai Gunungkidul","excerpt":"Turun ke Goa Jomblang pagi hari, menyeberang ke Pantai Timang dengan gondola sore harinya.","body":"Ini contoh artikel. Tulis artikel Anda sendiri di panel admin, menu Artikel.\n\nGunungkidul dua jam ke selatan Jogja. Tamu kami dari Prancis ingin goa dan laut, jadi kami jalani keduanya dalam satu hari panjang."}}'::jsonb, '/photos/jomblang.jpg', array['/photos/jomblang.jpg', '/photos/timang.jpg']::text[], '2026-09-12', true),
  ('sample-airport-pickup-at-midnight', '{"en":{"title":"Sample: an airport pickup at midnight","excerpt":"A late flight from Bali, a driver waiting at arrivals, and a quiet drive into the city.","body":"This is a sample article without extra photos. Write your own in the admin panel under Artikel.\n\nFlights land at YIA at every hour. Our drivers watch the flight times, so a delay never means waiting alone at the airport."},"id":{"title":"Contoh: jemput bandara tengah malam","excerpt":"Penerbangan malam dari Bali, sopir menunggu di kedatangan, lalu perjalanan tenang ke kota.","body":"Ini contoh artikel tanpa foto tambahan. Tulis artikel Anda sendiri di panel admin, menu Artikel.\n\nPesawat mendarat di YIA di jam berapa pun. Sopir kami memantau jadwal penerbangan, jadi keterlambatan tidak membuat tamu menunggu sendirian."}}'::jsonb, '/photos/kraton.jpg', array[]::text[], '2026-08-28', true);
